  </form>
  <script>
  (() => {
    const select = document.querySelector('select[name="mail_transport"]');
    const groups = document.querySelectorAll('[data-smtp-fields]');
    if (!select) return;
    const sync = () => {
      const smtp = select.value === 'smtp';
      groups.forEach(group => {
        group.hidden = !smtp;
        group.setAttribute('aria-hidden', smtp ? 'false' : 'true');
        group.querySelectorAll('input, select').forEach(input => {
          input.disabled = !smtp;
          input.required = smtp && (input.name === 'smtp_host' || input.name === 'smtp_port');
        });
      });
    };
    select.addEventListener('change', sync);
    sync();
  })();
  </script>
  <form method="post" data-no-async><input type="hidden" name="action" value="mail_test"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button secondary">Send test email to <?=e($u['email'])?></button></form>
</section>
