lLog as $mail):?><div class="admin-row"><span><?=e($mail['recipient_email'])?></span><span><?=e($mail['template_key']?:'Transactional')?></span><span><?=e(ucfirst($mail['status']))?></span><span><?=e($mail['created_at'])?></span></div><?php endforeach;?></div></section></div><section class="panel"><div class="admin-section-head"><h2>Automation status</h2><span>Run from hosting panel Scheduled Tasks</span></div><div class="admin-table"><div class="admin-row"><span><strong>Release announcements</strong><small>php private/bin/email-worker.php release</small></span><span>Last 7 days</span></div><div class="admin-row"><span><strong>Abandoned-cart reminders</strong><small>php private/bin/email-worker.php abandoned</small></span><span><?=$marketingStats['abandoned']?> waiting</span></div></div><p class="muted">Email templates are managed under Email Templates.</p></section><?php endif;?><?php endif;?><?php if($section==='help'):?><div class="section-title"><div><span class="kicker">OPERATIONS</span><h1>Scheduled Tasks Help</h1></div><span>Run automated emails without changing application code</span></div><section class="panel"><div class="admin-section-head"><h2>Recommended schedules</h2><span>Timezone: <?=e(date_default_timezone_get())?></span></div><div class="admin-table"><div class="admin-row"><span><strong>Abandoned basket reminders</strong><small>Run every hour. Each basket is reminded once after 24 hours.</small></span><code>0 * * * * /usr/bin/php <?=e(dirname(__DIR__))?>/private/bin/email-worker.php abandoned</code></div><div class="admin-row"><span><strong>New release announcements</strong><small>Run Mondays at 09:00. Sends releases from the previous seven days.</small></span><code>0 9 * * 1 /usr/bin/php <?=e(dirname(__DIR__))?>/private/bin/email-worker.php release</code></div></div></section><section class="panel"><div class="admin-section-head"><h2>External web cron</h2><span>For hosting without shell cron access</span></div><?php $workerSecret=(string)($config['app']['worker_secret']??'');if($workerSecret!==''):?><p class="muted">Use these URLs in a service such as cron-job.org. Keep the key private.</p><label>Abandoned basket URL<input readonly value="<?=e(url('worker.php?mode=abandoned&key='.$workerSecret))?>"></label><label>New releases URL<input readonly value="<?=e(url('worker.php?mode=release&key='.$workerSecret))?>"></label><?php else:?><p class="muted">No worker secret is configured. Add app.worker_secret to private config.php before using web cron.</p><?php endif;?></section><section class="panel"><div class="admin-section-head"><h2>hosting panel instructions</h2><span>Scheduled Tasks</span></div><ol><li>Open Websites &amp; Domains → Scheduled Tasks.</li><li>Select the system user that owns the application.</li><li>Add a command task using the commands above.</li><li>Set the task timezone to match the application timezone.</li></ol><p class="muted">Normal Linux cron uses the same commands. The website worker endpoint is available at <code><?=e(url('worker.php'))?></code>.</p><section class="panel operational-safeguards"><div class="admin-section-head"><h2>Operational safeguards</h2><span>Recommended maintenance tasks</span></div><div class="admin-table"><div class="admin-row"><span><strong>Database backup</strong><small>Run daily at 02:30. Keeps the last seven days of compressed backups.</small></span><code>php <?=e(dirname(__DIR__))?>/private/bin/backup-database.php</code></div><div class="admin-row"><span><strong>Application health check</strong><small>Run every 15 minutes. Returns a non-zero exit code if the database, storage paths or core tables fail.</small></span><code>php <?=e(dirname(__DIR__))?>/private/bin/health-check.php</code></div></div><p class="muted">For normal Linux cron, add the commands above to the application system user. In hosting panel, create command tasks under Websites &amp; Domains → Scheduled Tasks and select the same system user that owns the private application directory.</p></section></section><?php endif;?><?php if($section==='audit'):$auditRows=[];try{$auditRows=$pdo->query("SELECT l.id,l.event_type,l.user_agent,l.metadata_json,l.created_at,u.display_name,u.email,INET6_NTOA(l.ip_address) ip_address_text FROM audit_log l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC,l.id DESC LIMIT 500")->fetchAll();}catch(Throwable $ignored){}?><div class="section-title"><div><span class="kicker">SECURITY</span><h1>Audit Log</h1></div><span>Latest <?=count($auditRows)?> events</span></div><section class="panel admin-list-panel audit-log-panel"><div class="admin-section-head"><h2>Account and security activity</h2><span>IP address · browser agent</span></div><div class="audit-log-list"><div class="audit-log-row audit-log-head"><strong>When</strong><strong>Event</strong><strong>User</strong><strong>IP address</strong><strong>Browser agent</strong><strong>Details</strong></div><?php foreach($auditRows as $row):?><div class="audit-log-row"><span><?=e($row['created_at'])?></span><strong><?=e($row['event_type'])?></strong><span><?=e($row['display_name']?:$row['email']?:'System')?></span><span><?=e($row['ip_address_text']?:'Unknown')?></span><span class="audit-agent"><?=e($row['user_agent']?:'Unknown')?></span><span><?=e($row['metadata_json']?:'')?></span></div><?php endforeach;?><?php if(!$auditRows):?><p class="muted">No audit events are available yet. Apply the user-controls migration if this is a fresh deployment.</p><?php endif;?></div></section><?php endif;?>
