<?php if($section==='reporting'):?><section class="panel report-period-panel"><div class="admin-section-head"><div><h2>Period report</h2><span>Performance for the selected reporting window</span></div><form method="get" class="report-period-form"><input type="hidden" name="section" value="reporting"><label>Period<select name="days" onchange="this.form.submit()"><option value="7" <?=$reportDays===7?'selected':''?>>Last 7 days</option><option value="30" <?=$reportDays===30?'selected':''?>>Last 30 days</option><option value="90" <?=$reportDays===90?'selected':''?>>Last 90 days</option><option value="365" <?=$reportDays===365?'selected':''?>>Last 12 months</option></select></label></form></div><div class="admin-stat-grid"><div class="panel admin-stat"><span>Period revenue</span><strong><?=money((int)$periodRevenue)?></strong></div><div class="panel admin-stat"><span>Paid orders</span><strong><?=e((string)$periodOrders)?></strong></div><div class="panel admin-stat"><span>Order conversion</span><strong><?=e((string)($periodAllOrders>0?round(((int)$periodOrders/$periodAllOrders)*100,1):0))?>%</strong><small>Paid orders ÷ all orders</small></div><div class="panel admin-stat"><span>Downloads</span><strong><?=e((string)$periodDownloads)?></strong></div></div><div class="admin-section-head"><h2>Daily downloads</h2><span><?=e((string)$reportDays)?>-day window</span></div><div class="admin-table report-daily-table"><?php foreach($reportDaily as $day):?><div class="admin-row"><span><strong><?=e($day['report_date'])?></strong></span><span><?=e((string)$day['downloads'])?> downloads</span></div><?php endforeach;?><?php if(!$reportDaily):?><p class="muted">No downloads were recorded in this period.</p><?php endif;?></div></section><?php endif;?>
